#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    int values[100];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    for (int pass = 0; pass < n - 1; pass++) {
        bool swapped = false;
        for (int j = 0; j < n - 1 - pass; j++) {
            if (values[j] > values[j + 1]) {
                int tmp = values[j];
                values[j] = values[j + 1];
                values[j + 1] = tmp;
                swapped = true;
            }
        }
        for (int i = 0; i < n; i++) {
            printf(i + 1 < n ? "%d " : "%d\n", values[i]);
        }
        if (!swapped) {
            break;
        }
    }
    return 0;
}

