#include <stdio.h>
#include <string.h>

typedef struct {
    char name[21];
    int wins;
    int points;
} Team;

static bool after(const Team *a, const Team *b) {
    if (a->points != b->points) {
        return a->points < b->points;
    }
    if (a->wins != b->wins) {
        return a->wins < b->wins;
    }
    return strcmp(a->name, b->name) > 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    Team teams[100];
    for (int i = 0; i < n; i++) {
        int draws, losses;
        scanf("%20s %d %d %d", teams[i].name, &teams[i].wins, &draws, &losses);
        teams[i].points = 3 * teams[i].wins + draws;
    }
    for (int pass = 0; pass < n - 1; pass++) {
        for (int j = 0; j < n - 1 - pass; j++) {
            if (after(&teams[j], &teams[j + 1])) {
                Team tmp = teams[j];
                teams[j] = teams[j + 1];
                teams[j + 1] = tmp;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        printf("%d %s %d\n", i + 1, teams[i].name, teams[i].points);
    }
    return 0;
}

